#pragma oncestruct _256Header{	char plugName[32];			// Plug-in header (me)	long type;					// mesh .256 etc.	long name;	long plugHeaderQ1;	long plugHeaderQ2;	long plugHeaderOffset;	long plugLength;	long plugHeaderQ4;	long plugHeaderQ5;	long unknown1;	long unknown2;	long typeN; // ??? tm is 256, overhead for tm is 32	long unknown3;	char filler[48];	long palettes; // # of palettes? maybe just 1 or 0	long paletteOffset; // from the END of this header	long paletteLength; // 2080 bytes every time?	long paletteUnknown;	long unknown4;	long unknown5;	long unknown6;	long unknown7;	long sections; // # of textures/bitmaps in the file?? (18 for tm!)	long sectionInfoOffset; // offset from the END of this header to the section table	long sectionInfoLength; // 128 bytes per sectionInfo entry (18 * 128 = 2304 for tm)	long sectionInfoUnknown;	long bitmapDescriptors; // don't ask!	long bitmapDescriptorInfoOffset; // from the END of this header	long bitmapDescriptorInfoLength; // 64 bytes for each entry methinks	long bitmapDescriptorInfoUnknown; // btw, tm has none of these (bitmap descriptors)	long bitmapInfoHeaders; // ditto the don't ask above :)	long bitmapInfoHeaderOffset; // again, from the end of this header	long bitmapInfoHeaderLength; // 128 bytes each I believe	long bitmapInfoHeaderUnknown; // again, none for the tm	long godKnowsWhats;	long godKnowsWhatOffset;	long godKnowsWhatLength; // 32 bytes each???	long godKnowsWhatUnknown;	long colorMaps; // ??? this is that 65536 byte thing in the tm after the palette	long colorMapOffset; // in the tm this actually comes FIRST (0...255 is part of it)	long colorMapLength; // 65536 bytes for the maps methinks	long colorMapUnknown;	long colorMapIndices; // ??? no idea what this is	long colorMapIndexOffset; // unlike I originally thought, this came AFTER the 65536 in tm	long colorMapIndexLength; // 256 bytes each?	long colorMapIndexUnknown;	long unknowns[12]; // what appears to be 3 more possible tables	long unknown8;	long unknown9;	long headerLength; // 320 bytes	long tagLength; // length of data this header precedes	unsigned char filler2[64];}; // 320 bytesstruct sectionInfoEntry{	char filler1[64];	unsigned long offset; 		// from the END of the _256Header	long length; 				// 65536 + 52 bytes I think	long unknown2;	long unknown3;	char filler2[48];}; 							// 128 bytesstruct textureHeader{	char u1, u2, u3;	int type; // 33 = shadow, 1185 = texture	char u4, u5, u6, u7;	char filler1[32]; // no clue	int u8, u9;}; // 52 bytesstruct Myth256Palette										// 2080 bytes{	long colors;											// # of colors	long unk1, unk2, unk3;	long unk4, unk5, unk6, unk7;	struct RGBinfo { unsigned char red, fillerr, green, fillerg, blue, fillerb, flag, fillerf; } color[256];};